        {
            "_id": "6a86fffc71485a01c973231b",
            "user": "6a775585a2d640734f0df82f",
            "title": "My title",
            "description": "This is our first note and fantastic.",
            "tag": "personal",
            "date": "2026-08-20T13:24:12.359Z",
            "__v": 0
        },
        {
            "_id": "6a87004571485a01c973231c",
            "user": "6a775585a2d640734f0df82f",
            "title": "React Project",
            "description": "It is the method of fetching notes",
            "tag": "Self",
            "date": "2026-08-20T13:25:25.133Z",
            "__v": 0
        }
    ]

    return (
        <Notecontext.Provider value={{ notes }}>
            {props.children}
        </Notecontext.Provider>
    )
}

export default Notestate;
